#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int n;        cin >> n;        vector<int> p(n), sufMax(n);        for (int i = 0; i < n; i++) cin >> p[i];         sufMax[n - 1] = p[n - 1];        for (int i = n - 2; i >= 0; i--) {            sufMax[i] = max(sufMax[i + 1], p[i]);        }         int i = -1;        for (int k = 0; k < n; k++) {            if (p[k] != sufMax[k]) {                i = k;                break;            }        }         if (i != -1) {            int mx = sufMax[i];            int j = i;            for (int k = n - 1; k >= i; k--) {                if (p[k] == mx) {                    j = k;                    break;                }            }            reverse(p.begin() + i, p.begin() + j + 1);        }         for (int x : p) cout << x << " ";        cout << "\n";    }}